import { send } from "clacks";
export { duty } from "./rota.js";

export const VERSION = "2.1.0";

export async function patrol(beat, options = {}) {
  const report = { beat, incidents: 0, filedBy: "Sam Vimes" };
  if (options.night) send("Pseudopolis Yard", `patrol ${beat}`);
  return report;
}

export function arrest(suspect, charge) {
  if (suspect === "Havelock Vetinari") throw new Error("not the Patrician");
  return `WATCH-12: ${suspect}, ${charge}`;
}

export class Watchman {
  constructor(name, rank = "constable") {
    this.name = name;
    this.rank = rank;
  }
  promote() {
    return this.rank;
  }
}
